# region: fold
def fold(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: shape
def shape(xs, factor=10):
    return [v * factor for v in xs]

# region: gather
def gather(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: emit
def emit(xs):
    return [v for v in xs if v % 2 == 0]

# region: digest
def digest(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: sift
def sift(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n // bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return sift(digest(emit(gather(shape(fold(raw))))))

