import unittest
from program import run

class T(unittest.TestCase):
    def test_case_00(self):
        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'total': 60, 'ratio': 1.5})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 2, 'total': 170, 'ratio': 1.0})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 2, 'total': 130, 'ratio': 1.0})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'total': 0, 'ratio': 0.0})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'total': 250, 'ratio': 1.5})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 0, 'total': 0, 'ratio': 0.0})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'total': 240, 'ratio': 2.0})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 2, 'total': 420, 'ratio': 1.0})

if __name__ == '__main__':
